    private static let byKey = Dictionary(uniqueKeysWithValues: entries.map { ($0.key, $0) })

    static func entry(for key: String, profile: ProvisioningProfile) -> Entry? {
        guard let entry = byKey[key] else { return nil }
        // Some capabilities can be enabled for development without Apple approval.
        // Missing authorization in that case remains subject to Strict/Compatible.
        if entry.scope == .distributionOnly && profile.distribution == "Development" { return nil }
        return entry
    }
